<style>
:root{--brand:#d97706;--brand-dark:#92400e;--ink:#172033;--muted:#667085;--line:#e5e7eb;--surface:#fff;--danger:#b42318}*{box-sizing:border-box}body{margin:0;background:linear-gradient(180deg,#fff7ed 0,#f5f6f8 260px);color:var(--ink);font:16px/1.5 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{max-width:760px;margin:auto;padding:18px}.card{background:rgba(255,255,255,.98);border:1px solid rgba(229,231,235,.9);border-radius:20px;padding:20px;margin-bottom:16px;box-shadow:0 10px 30px rgba(15,23,42,.06)}.hero{padding:24px;background:linear-gradient(135deg,#fffbeb,#fff7ed);border-color:#fed7aa}.kicker{display:block;color:var(--brand-dark);font-size:.76rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.hero h1{margin:5px 0 6px;font-size:1.6rem;line-height:1.2}.hero p,.muted{margin:0;color:var(--muted)}h2{font-size:1.15rem;margin:0 0 5px}.hint{margin:0 0 17px;color:var(--muted);font-size:.9rem}.form-grid{display:grid;grid-template-columns:1.35fr 1fr 1fr;gap:12px}label{display:block;font-size:.86rem;font-weight:750}input{width:100%;min-height:46px;margin-top:5px;padding:10px 12px;border:1px solid #d0d5dd;border-radius:11px;background:#fff;color:var(--ink);font:inherit}input:focus{outline:0;border-color:#f59e0b;box-shadow:0 0 0 3px rgba(245,158,11,.16)}button{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:46px;border:0;border-radius:12px;padding:11px 16px;background:var(--brand);color:#fff;font:inherit;font-weight:780;cursor:pointer}.add{width:100%;margin-top:16px}.day{margin-top:18px}.day:first-child{margin-top:4px}.day-title{display:flex;align-items:center;gap:9px;margin:0 0 9px;font-size:.93rem;text-transform:capitalize}.day-title:after{content:"";height:1px;flex:1;background:var(--line)}.slot{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px;margin-top:8px;border:1px solid var(--line);border-radius:14px;background:#f8fafc}.time{font-size:1.08rem;font-weight:800}.slot-meta{display:block;color:var(--muted);font-size:.82rem}.delete{min-height:38px;padding:8px 11px;background:#fff;color:var(--danger);border:1px solid #fecaca}.locked{display:inline-flex;align-items:center;padding:6px 9px;border-radius:999px;background:#fef3c7;color:#92400e;font-size:.76rem;font-weight:750}.empty{text-align:center;padding:25px 12px;color:var(--muted)}.ok,.error{padding:13px 15px;border-radius:12px;margin-bottom:14px}.ok{background:#dcfce7;color:#166534}.error{background:#fee2e2;color:#991b1b}.footer{text-align:center;color:#98a2b3;font-size:.78rem;padding:4px 0 18px}@media(max-width:600px){body{background:linear-gradient(180deg,#fff7ed 0,#f5f6f8 190px)}.wrap{padding:12px}.card{padding:16px;border-radius:17px;margin-bottom:12px}.hero{padding:19px}.hero h1{font-size:1.4rem}.form-grid{grid-template-columns:1fr 1fr}.form-grid label:first-child{grid-column:1/-1}.slot{padding:13px 12px}.delete{font-size:.85rem}.locked{max-width:140px;text-align:center}.add{position:sticky;bottom:max(10px,env(safe-area-inset-bottom));box-shadow:0 8px 20px rgba(146,64,14,.22)}}
</style></head><body><main class="wrap">
